package main

import (
	"fmt"
	"io"
	"log"
	"net/http"
)

// TaxCalculator provides methods to calculate tax based on income.
type TaxCalculator struct{}

// CalculateTax calculates the income tax based on a progressive tax system.
// This implementation contains subtle bugs to be identified and fixed.
func (tc *TaxCalculator) CalculateTax(income float64) float64 {
	var tax float64

	switch {
	case income <= 10000:
		tax = income * 0.10 // 10% for income up to 10,000
	case income <= 30000:
		// Bug: Incorrectly applies 20% to the entire income, not just the marginal amount
		// Also, doesn't correctly add tax from previous bracket
		tax = income * 0.20 // 20% for income between 10,001 and 30,000
	case income <= 60000:
		// Bug: Similar issue as above, not correctly calculating marginal tax
		tax = income * 0.30 // 30% for income between 30,001 and 60,000
	default:
		// Bug: Similar issue, applies 40% to entire income
		tax = income * 0.40 // 40% for income above 60,000
	}

	return tax
}

func helloHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	name := r.URL.Query().Get("name")
	if name == "" {
		name = "World"
	}
	fmt.Fprintf(w, "Hello, %s!", name)
}

func echoHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	body, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Failed to read body", http.StatusInternalServerError)
		return
	}
	defer r.Body.Close()
	w.Write(body)
}

func setupRoutes() *http.ServeMux {
	mux := http.NewServeMux()
	mux.HandleFunc("/hello", helloHandler)
	mux.HandleFunc("/echo", echoHandler)
	return mux
}

func main() {
	mux := setupRoutes()
	log.Println("Server starting on :8080")
	if err := http.ListenAndServe(":8080", mux); err != nil {
		log.Fatal(err)
	}
}

package main

import (
	"math"
	"testing"
)
 unc TestCalculateTax(t *testing.T) {
	tc := &TaxCalculator{}

	tests := []struct {
		name   string
		income float64
		expectedTax float64
	}{
		{
			name:   "Income within first bracket",
			income: 5000,
			expectedTax: 500.00,
		},
		{
			name:   "Income at upper bound of first bracket",
			income: 10000,
			expectedTax: 1000.00,
		},
		{
			name:   "Income just above first bracket",
			income: 10001,
			expectedTax: 1000.00 + (1 * 0.20), // 1000 (from 1st bracket) + 0.20 (from 2nd bracket)
		},
		{
			name:   "Income within second bracket",
			income: 15000,
			expectedTax: 2000.00, // 1000 (from 1st) + (5000 * 0.20) = 1000 + 1000 = 2000
		},
		{
			name:   "Income at upper bound of second bracket",
			income: 30000,
			expectedTax: 5000.00, // 1000 (from 1st) + (20000 * 0.20) = 1000 + 4000 = 5000
		},
		{
			name:   "Income just above second bracket",
			income: 30001,
			expectedTax: 5000.00 + (1 * 0.30), // 5000 (from 1st+2nd) + 0.30 (from 3rd)
		},
		{
			name:   "Income within third bracket",
			income: 40000,
			expectedTax: 8000.00, // 5000 (from 1st+2nd) + (10000 * 0.30) = 5000 + 3000 = 8000
		},
		{
			name:   "Income at upper bound of third bracket",
			income: 60000,
			expectedTax: 14000.00, // 5000 (from 1st+2nd) + (30000 * 0.30) = 5000 + 9000 = 14000
		},
		{
			name:   "Income just above third bracket",			income: 60001,
			expectedTax: 14000.00 + (1 * 0.40), // 14000 (from 1st+2nd+3rd) + 0.40 (from 4th)
		},
		{
			name:   "Income in highest bracket",
			income: 70000,
			expectedTax: 18000.00, // 14000 (from 1st+2nd+3rd) + (10000 * 0.40) = 14000 + 4000 = 18000
		},
		{
			name:   "Zero income",
			income: 0,
			expectedTax: 0.00,
		},
		{
			name:   "Negative income (should be 0 tax)",
			income: -100,
			expectedTax: 0.00,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			actualTax := tc.CalculateTax(tt.income)
			// Using a small epsilon for float comparison
			if math.Abs(actualTax-tt.expectedTax) > 0.001 {
				t.Errorf("For income %f, expected tax %.2f, but got %.2f", tt.income, tt.expectedTax, actualTax)
			}
		})
	}
}

